package com.company.platform.order.domain;
import java.time.Instant; import java.util.*;
public final class Order {private final UUID id,tenantId,customerId,storeId;private final OrderNumber orderNumber;private final List<OrderItem> items=new ArrayList<>();private OrderStatus status;private final Currency currency;private Money subtotal;private final Instant createdAt;private Instant updatedAt;
 private Order(UUID id,UUID tenantId,OrderNumber n,UUID customerId,UUID storeId,OrderStatus s,Currency c,Money subtotal,Instant created,Instant updated,List<OrderItem> items){if(tenantId==null||n==null||customerId==null||storeId==null||c==null)throw new IllegalArgumentException("order ownership required");this.id=id==null?UUID.randomUUID():id;this.tenantId=tenantId;this.orderNumber=n;this.customerId=customerId;this.storeId=storeId;this.status=s==null?OrderStatus.DRAFT:s;this.currency=c;this.subtotal=subtotal==null?Money.zero(c):subtotal;this.createdAt=created==null?Instant.now():created;this.updatedAt=updated==null?this.createdAt:updated;if(items!=null)this.items.addAll(items);}
 public static Order create(UUID tenantId,OrderNumber n,UUID customerId,UUID storeId,Currency c){return new Order(null,tenantId,n,customerId,storeId,null,c,null,null,null,null);}public static Order rehydrate(UUID id,UUID t,OrderNumber n,UUID c,UUID s,OrderStatus st,Currency cur,Money sub,Instant ca,Instant ua,List<OrderItem> i){return new Order(id,t,n,c,s,st,cur,sub,ca,ua,i);}public void addItem(OrderItem i){if(status!=OrderStatus.DRAFT)throw new IllegalStateException("order is immutable after submission");if(!i.orderId().equals(id)||!i.unitPrice().currency().equals(currency))throw new IllegalArgumentException("item does not belong to order");items.add(i);recalculate();}public void submit(){if(items.isEmpty())throw new IllegalStateException("order needs items");transition(OrderStatus.PENDING_CONFIRMATION);}public void confirm(){if(status!=OrderStatus.PENDING_CONFIRMATION)throw new IllegalStateException("invalid confirmation");transition(OrderStatus.CONFIRMED);}public void cancel(){if(status.terminal()||status==OrderStatus.PROCESSING)throw new IllegalStateException("invalid cancellation");transition(OrderStatus.CANCELLED);}public void expire(){if(status!=OrderStatus.PENDING_CONFIRMATION)throw new IllegalStateException("invalid expiration");transition(OrderStatus.EXPIRED);}public void startProcessing(){if(status!=OrderStatus.CONFIRMED)throw new IllegalStateException("invalid processing");transition(OrderStatus.PROCESSING);}public void complete(){if(status!=OrderStatus.PROCESSING)throw new IllegalStateException("invalid completion");transition(OrderStatus.COMPLETED);}private void transition(OrderStatus s){status=s;updatedAt=Instant.now();}private void recalculate(){subtotal=items.stream().map(OrderItem::subtotal).reduce(Money.zero(currency),Money::add);updatedAt=Instant.now();}
 public UUID id(){return id;}public UUID tenantId(){return tenantId;}public OrderNumber orderNumber(){return orderNumber;}public UUID customerId(){return customerId;}public UUID storeId(){return storeId;}public OrderStatus status(){return status;}public Currency currency(){return currency;}public Money subtotal(){return subtotal;}public List<OrderItem> items(){return List.copyOf(items);}public Instant createdAt(){return createdAt;}public Instant updatedAt(){return updatedAt;}}
